+// Who may call what. `viewer` may only read; `cook` may also cook, record
+// waste, log temperatures and enter stock-take counts; `manager` may do
+// everything. Manager-only reads are listed in MANAGER_READS.
+import { AppError } from "../errors.js";
+
+const COOK_WRITES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+const MANAGER_READS = new Set(["GET /audit"]);
+
+/** The key from an `Authorization: Bearer <key>` header, or null. */
+export function bearerKey(headers = {}) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const value = name === undefined ? "" : String(headers[name]);
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(value);
+  return m ? m[1] : null;
+}
+
+/** Whether `role` may call the route `method pattern`. */
+export function allowed(role, method, pattern) {
+  const route = `${method} ${pattern}`;
+  if (role === "manager") return true;
+  if (method === "GET" && !MANAGER_READS.has(route)) return role === "viewer" || role === "cook";
+  return role === "cook" && COOK_WRITES.has(route);
+}
+
+/** Throws `forbidden` unless `role` may call the route. */
+export function authorize(role, method, pattern) {
+  if (!allowed(role, method, pattern)) throw new AppError("forbidden");
+}
